// Defensive input validation -- this workflow could in principle be called
// directly (e.g. a future WhatsApp-based support/CRM front door, or manual
// testing via `n8n execute`), not only via
// workflows/integrations/01-whatsapp-gateway-webhook.json's "Ready For AI /
// CRM Processing" branch, so it never trusts its caller blindly -- same
// posture as 02-finance-intent-router.json's "Validate Request Contract"
// and 10-handle-create-expense.json's "Validate Handler Input".
//
// This checks the shape THIS ADAPTER needs to build a Finance Inbox
// Request and a WhatsApp reply. It is NOT the Finance Inbox Request
// Contract shape (that's built next, in "Build Finance Inbox Request") and
// it is NOT Finance-specific validation -- no amount/category/date rules
// belong here at all.
const req = $json || {};
const reasons = [];

function requireNonEmptyString(field) {
  if (typeof req[field] !== 'string' || req[field].trim().length === 0) {
    reasons.push(`Missing/empty required field: ${field}.`);
  }
}

// workflowExecutionId: this adapter's one hard requirement. Without it
// there is no idempotency key to thread through the Router/Handler/Finance
// API chain -- see ADR-0013 for why this adapter reuses the Gateway's own
// value rather than generating one itself.
requireNonEmptyString('workflowExecutionId');
// customerWhatsappId: this adapter's own reply-routing requirement (mirrors
// 10-handle-create-expense.json's Handler-specific externalUserId rule) --
// without a real WhatsApp ID there is no safe recipient for any reply,
// success or failure.
requireNonEmptyString('customerWhatsappId');

return [{
  json: {
    valid: reasons.length === 0,
    reason: reasons.join(' '),
    workflowExecutionId: req.workflowExecutionId,
    customerWhatsappId: req.customerWhatsappId || null,
    messageId: req.messageId || null,
    messageType: req.messageType || null,
    messageText: typeof req.messageText === 'string' ? req.messageText : '',
  },
}];

// Malformed/unexpected input from whatever called this workflow -- logged
// for diagnosis. No WhatsApp reply is attempted here since a safe
// recipient could not even be confirmed (see "Validate WhatsApp Event
// Input"). This never reaches the Finance Intent Router.
const v = $json;
console.log(`[Build Invalid Event Response] Rejected malformed WhatsApp event: ${v.reason}`);
return [{ json: { dispatched: false, reason: v.reason } }];

// Maps the WhatsApp-native envelope (already normalized by
// 01-whatsapp-gateway-webhook.json's "Normalize WhatsApp Messages") onto
// the channel-agnostic Finance Inbox Request Contract (ADR-0008 Decision 1,
// docs/workflows/finance-inbox-contract.md). WhatsApp-specific fields
// (customerWhatsappId, messageId, messageType) are deliberately NOT
// forwarded past this node into the Router -- they stay local to this
// adapter, referenced later by node name ($('Validate WhatsApp Event
// Input')) the same way 01-finance-inbox-entry.json keeps
// slackChannelId/slackThreadTs local to itself rather than threading them
// through the Router.
//
// workflowExecutionId is NOT generated here via $execution.id. This
// workflow is not the true channel-entry boundary -- the Gateway
// (workflows/integrations/01-whatsapp-gateway-webhook.json) is, since it
// owns the actual Meta webhook trigger. The Gateway already generated
// workflowExecutionId as ITS OWN $execution.id (in its "Normalize WhatsApp
// Messages" node) and this adapter forwards that value unchanged, exactly
// like every other downstream hop in this chain (Router, Handler). See
// docs/adrs/ADR-0013-whatsapp-finance-entry-adapter.md for the full
// reasoning.
//
// workflowName IS this adapter's own slug, not the Gateway's -- matching
// the established per-hop-self-identifies convention
// (workflows/crm/03-ai-qualification.json's "Call AI Core",
// 10-handle-create-expense.json's own Finance API call).
const input = $('Validate WhatsApp Event Input').item.json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: input.workflowExecutionId,
    workflowName: '03-whatsapp-finance-entry',
    channel: 'whatsapp',
    externalUserId: input.customerWhatsappId,
    externalMessageId: input.messageId,
    rawText: input.messageText,
    // WhatsApp media messages are not yet extracted as attachments -- the
    // Gateway itself does not resolve WhatsApp media IDs to downloadable
    // URLs (a separate, authenticated Graph API call it does not currently
    // make). Always [] until that capability exists -- see this workflow's
    // documentation, "Known Limitations".
    attachments: [],
  },
}];

// "Call Finance Intent Router" has onError: continueRegularOutput, so a
// failed call surfaces as $json.error here rather than crashing -- same
// pattern as 01-finance-inbox-entry.json's "Format Slack Reply" reading
// $json.error after "Call Finance Intent Router". This node never inspects
// intent/category/amount/any Finance-specific field -- its only job is
// translating the Response Contract's `message` into
// 02-whatsapp-outbound-send.json's own input contract, with a safe
// fallback when the Router call itself failed or `message` is missing.
const input = $('Validate WhatsApp Event Input').item.json;
const result = $json || {};

let text;
if (result.error) {
  const message = String((result.error && result.error.message) || result.error);
  text = "Sorry, I couldn't process that just now. Please try again in a moment.";
  console.log(`[Build WhatsApp Reply Input] Finance Intent Router call failed: ${message}`);
} else if (typeof result.message === 'string' && result.message.trim()) {
  text = result.message;
} else {
  text = "Sorry, I couldn't process that just now. Please try again in a moment.";
}

return [{
  json: {
    to: input.customerWhatsappId,
    messageType: 'text',
    text,
    contextTag: 'finance-inbox-response',
  },
}];
